@Dao interface DraftDao {
  @Insert suspend fun insert(d: DraftEntity)
  @Query("SELECT * FROM drafts ORDER BY createdAt") suspend fun all(): List<DraftEntity>
  @Delete suspend fun delete(d: DraftEntity)
}

class UploadDraftsWorker(ctx: Context, p: WorkerParameters) : CoroutineWorker(ctx, p) {
  override suspend fun doWork(): Result { for (d in dao.all()) { api.create(d.toNote()); dao.delete(d) }; return Result.success() }
}

